// SystemInit.jsx
import React, { useState } from 'react';
import './SystemInit.css';
import CompanyLogo from "../../../src/assets/gm_edited.png";

const STEPS = [
  { key: 1, label: 'Asset Profile', hint: 'Pipeline parameters' },
  { key: 2, label: 'Contacts', hint: 'Ownership & escalation' },
  { key: 3, label: 'Compliance', hint: 'Reporting frameworks' },
];

const SystemInit = ({ onComplete }) => {
  const [activeStep, setActiveStep] = useState(1);
  const [formData, setFormData] = useState({
    // step 1 — asset profile
    operatorName: 'Yunoya LTD',
    county: 'Midland',
    location: 'Permian Basin',
    material: 'Steel',
    type: 'Transmission',
    // step 2 — contacts
    primaryContact: '',
    primaryEmail: '',
    primaryPhone: '',
    escalationContact: '',
    // step 3 — compliance
    phmsa: true,
    trrc: true,
    notes: '',
  });

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prev) => ({ ...prev, [name]: type === 'checkbox' ? checked : value }));
  };

  const handleNext = () => {
    if (activeStep < 3) setActiveStep(activeStep + 1);
    else if (onComplete) onComplete(formData);
  };

  const handlePrev = () => {
    if (activeStep > 1) setActiveStep(activeStep - 1);
  };

  const handleStepClick = (step) => {
    // only allow jumping to steps already reached
    if (step <= activeStep) setActiveStep(step);
  };

  return (
    <div className="init-page">
      {/* Identity strip */}
      <header className="init-header">
        <img src={CompanyLogo} alt="Galaxy Midstream" className="init-header-logo" />
        <div className="init-header-text">
          <span className="init-wordmark">GALAXY</span>
          <span className="init-wordmark-sub">COMPLIANCE SYSTEM</span>
        </div>
        <div className="init-header-meta">
          <i className="fas fa-terminal"></i>
          <span>SYSTEM INITIALIZATION</span>
        </div>
      </header>

      <div className="init-body">
        {/* Vertical step rail */}
        <aside className="init-rail">
          {STEPS.map((step, idx) => {
            const state =
              step.key === activeStep ? 'active' : step.key < activeStep ? 'done' : 'pending';
            return (
              <React.Fragment key={step.key}>
                <button
                  className={`init-rail-step init-rail-step--${state}`}
                  onClick={() => handleStepClick(step.key)}
                  disabled={state === 'pending'}
                >
                  <span className="init-rail-index">
                    {state === 'done' ? <i className="fas fa-check"></i> : String(step.key).padStart(2, '0')}
                  </span>
                  <span className="init-rail-copy">
                    <span className="init-rail-label">{step.label}</span>
                    <span className="init-rail-hint">{step.hint}</span>
                  </span>
                </button>
                {idx < STEPS.length - 1 && <span className="init-rail-connector"></span>}
              </React.Fragment>
            );
          })}
        </aside>

        {/* Active step panel */}
        <section className="init-panel">
          <div className="init-panel-head">
            <span className="init-panel-eyebrow">STEP {String(activeStep).padStart(2, '0')} / 03</span>
            <h2 className="init-panel-title">{STEPS[activeStep - 1].label}</h2>
            <p className="init-panel-sub">
              {activeStep === 1 && 'Configure your primary pipeline parameters.'}
              {activeStep === 2 && 'Assign the people responsible for this asset.'}
              {activeStep === 3 && 'Confirm which reporting frameworks apply.'}
            </p>
          </div>

          <div className="init-form">
            {activeStep === 1 && (
              <>
                <div className="init-form-group">
                  <label className="init-label">Operator Name</label>
                  <input
                    type="text"
                    name="operatorName"
                    className="init-input"
                    value={formData.operatorName}
                    onChange={handleInputChange}
                  />
                </div>

                <div className="init-form-row">
                  <div className="init-form-group">
                    <label className="init-label">County</label>
                    <input
                      type="text"
                      name="county"
                      className="init-input"
                      value={formData.county}
                      onChange={handleInputChange}
                    />
                  </div>
                  <div className="init-form-group">
                    <label className="init-label">Location</label>
                    <input
                      type="text"
                      name="location"
                      className="init-input"
                      value={formData.location}
                      onChange={handleInputChange}
                    />
                  </div>
                </div>

                <div className="init-form-row">
                  <div className="init-form-group">
                    <label className="init-label">Material</label>
                    <select
                      name="material"
                      className="init-select"
                      value={formData.material}
                      onChange={handleInputChange}
                    >
                      <option value="Steel">Steel</option>
                      <option value="Plastic">Plastic</option>
                      <option value="Cast Iron">Cast Iron</option>
                      <option value="Copper">Copper</option>
                    </select>
                  </div>
                  <div className="init-form-group">
                    <label className="init-label">Type</label>
                    <select
                      name="type"
                      className="init-select"
                      value={formData.type}
                      onChange={handleInputChange}
                    >
                      <option value="Transmission">Transmission</option>
                      <option value="Distribution">Distribution</option>
                      <option value="Gathering">Gathering</option>
                    </select>
                  </div>
                </div>
              </>
            )}

            {activeStep === 2 && (
              <>
                <div className="init-form-row">
                  <div className="init-form-group">
                    <label className="init-label">Primary Contact</label>
                    <input
                      type="text"
                      name="primaryContact"
                      className="init-input"
                      placeholder="Full name"
                      value={formData.primaryContact}
                      onChange={handleInputChange}
                    />
                  </div>
                  <div className="init-form-group">
                    <label className="init-label">Escalation Contact</label>
                    <input
                      type="text"
                      name="escalationContact"
                      className="init-input"
                      placeholder="Full name"
                      value={formData.escalationContact}
                      onChange={handleInputChange}
                    />
                  </div>
                </div>

                <div className="init-form-row">
                  <div className="init-form-group">
                    <label className="init-label">Email</label>
                    <input
                      type="email"
                      name="primaryEmail"
                      className="init-input"
                      placeholder="name@company.com"
                      value={formData.primaryEmail}
                      onChange={handleInputChange}
                    />
                  </div>
                  <div className="init-form-group">
                    <label className="init-label">Phone</label>
                    <input
                      type="tel"
                      name="primaryPhone"
                      className="init-input"
                      placeholder="(000) 000-0000"
                      value={formData.primaryPhone}
                      onChange={handleInputChange}
                    />
                  </div>
                </div>
              </>
            )}

            {activeStep === 3 && (
              <>
                <div className="init-checkbox-group">
                  <label className="init-checkbox-row">
                    <input
                      type="checkbox"
                      name="phmsa"
                      checked={formData.phmsa}
                      onChange={handleInputChange}
                    />
                    <span className="init-checkbox-box"></span>
                    <span className="init-checkbox-copy">
                      <span className="init-checkbox-title">PHMSA (49 CFR)</span>
                      <span className="init-checkbox-desc">Federal pipeline safety framework</span>
                    </span>
                  </label>
                  <label className="init-checkbox-row">
                    <input
                      type="checkbox"
                      name="trrc"
                      checked={formData.trrc}
                      onChange={handleInputChange}
                    />
                    <span className="init-checkbox-box"></span>
                    <span className="init-checkbox-copy">
                      <span className="init-checkbox-title">Texas TRRC (16 TAC)</span>
                      <span className="init-checkbox-desc">State railroad commission rules</span>
                    </span>
                  </label>
                </div>

                <div className="init-form-group">
                  <label className="init-label">Notes</label>
                  <textarea
                    name="notes"
                    className="init-textarea"
                    rows={3}
                    placeholder="Anything the compliance lead should know before go-live..."
                    value={formData.notes}
                    onChange={handleInputChange}
                  />
                </div>
              </>
            )}
          </div>

          <div className="init-actions">
            <button
              className="init-btn-ghost"
              onClick={handlePrev}
              disabled={activeStep === 1}
            >
              <i className="fas fa-arrow-left"></i>
              BACK
            </button>
            <button className="init-btn-primary" onClick={handleNext}>
              {activeStep < 3 ? (
                <>
                  PROCEED
                  <i className="fas fa-arrow-right"></i>
                </>
              ) : (
                <>
                  INITIALIZE SYSTEM
                  <i className="fas fa-check"></i>
                </>
              )}
            </button>
          </div>
        </section>
      </div>
    </div>
  );
};

export default SystemInit;
